const TEST_MODE = true;
const input = $input.first().json;
const b = input.body;
const errors = [];
const isObject = b !== null && typeof b === 'object' && !Array.isArray(b);
if (!isObject) errors.push('body_must_be_object');
if (isObject) {
  const allowed = ['ticket_id','email','message'];
  if (TEST_MODE) allowed.push('simulate');
  if (Object.keys(b).some(k => !allowed.includes(k))) errors.push('unknown_field');
  if (typeof b.ticket_id !== 'string' || !/^TKT-[0-9]{3}$/.test(b.ticket_id)) errors.push('invalid_ticket_id');
  if (typeof b.email !== 'string' || b.email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(b.email)) errors.push('invalid_email');
  if (typeof b.message !== 'string' || b.message.trim().length < 10 || b.message.trim().length > 2000) errors.push('invalid_message');
  if (TEST_MODE && b.simulate !== undefined && !['normal','unavailable','invalid_json','invalid_label','invalid_confidence'].includes(b.simulate)) errors.push('invalid_simulation');
}
if (errors.length) return [{json:{ready:true,http_status:400,response:{ok:false,error:'validation_error',details:errors}}}];
return [{json:{ready:false,ticket:{ticket_id:b.ticket_id,email:b.email.trim().toLowerCase(),message:b.message.trim()},simulate:TEST_MODE ? (b.simulate || 'normal') : 'normal'}}];

const item = $input.first().json;
if (item.ready) return [{json:item}];
if (item.simulate === 'unavailable') return [{json:{...item,provider_error:'simulated_unavailable'}}];
if (item.simulate === 'invalid_json') return [{json:{...item,raw_output:'not-json'}}];
const text = item.ticket.message.toLowerCase();
// Deterministic stub, not an AI model. Mixed categories use explicit precedence.
let category = 'general';
if (/\b(refund|invoice|payment|charged)\b/.test(text)) category = 'billing';
else if (/\b(error|crash|login|password)\b/.test(text)) category = 'technical';
else if (/\b(shipping|delivery|parcel|tracking)\b/.test(text)) category = 'shipping';
const priority = /\b(urgent|immediately)\b/.test(text) ? 'high' : 'normal';
const confidence = category === 'general' ? 0.4 : 0.9;
const output = {category,priority,confidence};
if (item.simulate === 'invalid_label') output.category = 'admin';
if (item.simulate === 'invalid_confidence') output.confidence = 5;
return [{json:{...item,raw_output:JSON.stringify(output)}}];

const item = $input.first().json;
if (item.ready) return [{json:item}];
if (item.provider_error) return [{json:{ready:true,http_status:503,response:{ok:false,error:'classifier_unavailable',ticket_id:item.ticket.ticket_id}}}];
let output;
try { output = JSON.parse(item.raw_output); } catch { output = null; }
const valid = output && typeof output === 'object' && !Array.isArray(output)
  && Object.keys(output).sort().join(',') === 'category,confidence,priority'
  && ['billing','technical','shipping','general'].includes(output.category)
  && ['high','normal'].includes(output.priority)
  && typeof output.confidence === 'number' && Number.isFinite(output.confidence)
  && output.confidence >= 0 && output.confidence <= 1;
if (!valid) return [{json:{ready:true,http_status:502,response:{ok:false,error:'invalid_classifier_output',ticket_id:item.ticket.ticket_id}}}];
const routes = {billing:'billing_queue',technical:'technical_queue',shipping:'shipping_queue',general:'manual_review'};
const queue = output.confidence < 0.7 ? 'manual_review' : routes[output.category];
return [{json:{ready:true,http_status:200,response:{ok:true,ticket_id:item.ticket.ticket_id,category:output.category,priority:output.priority,queue,confidence:output.confidence,classification_source:'deterministic_stub'}}}];
